// Store RPC response topic if present
if (msg.rpcResponseTopic) {
    flow.set("def_rpc_response_topic", msg.rpcResponseTopic);
}

// Generator and Battery daily energy
// 62: Today Gen
// 63-69: (skip)
// 70: Day Batt Charge
// 71: Day Batt Discharge

msg.baseAddr = 62;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 62,
    quantity: 10  // 62-71
};
return msg;

// Grid and Load daily energy
// 76: Day Grid Buy
// 77: Day Grid Sell
// 78-83: (skip)
// 84: Day Load

msg.baseAddr = 76;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 76,
    quantity: 9  // 76-84
};
return msg;

// PV daily energy
// 108: Day PV Power

msg.baseAddr = 108;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 108,
    quantity: 1
};
return msg;

// Build DailyEnergyFlowState from multiple Modbus reads.

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

let baseAddr = msg.baseAddr;
if (typeof baseAddr !== "number") {
    baseAddr = (msg.modbusRequest && msg.modbusRequest.address);
}
if (typeof baseAddr !== "number") {
    node.warn("DailyEnergyFlowState: missing base address");
    return null;
}

// ---- Store partials ----

// Gen/Batt 62-71
if (baseAddr === 62) {
    const genEnergy = data[0] || 0;          // 62
    const battCharge = data[8] || 0;         // 70
    const battDischarge = data[9] || 0;      // 71

    flow.set("def_part_gen_batt", {
        genEnergyKWh: Math.round((genEnergy * 0.1) * 10) / 10,
        chargeEnergyKWh: Math.round((battCharge * 0.1) * 10) / 10,
        dischargeEnergyKWh: Math.round((battDischarge * 0.1) * 10) / 10
    });
}

// Grid/Load 76-84
else if (baseAddr === 76) {
    const gridBuy = data[0] || 0;            // 76
    const gridSell = data[1] || 0;           // 77
    const loadEnergy = data[8] || 0;         // 84

    flow.set("def_part_grid_load", {
        importEnergyKWh: Math.round((gridBuy * 0.1) * 10) / 10,
        exportEnergyKWh: Math.round((gridSell * 0.1) * 10) / 10,
        loadEnergyKWh: Math.round((loadEnergy * 0.1) * 10) / 10
    });
}

// PV 108
else if (baseAddr === 108) {
    const pvEnergy = data[0] || 0;           // 108

    flow.set("def_part_pv", {
        pvEnergyKWh: Math.round((pvEnergy * 0.1) * 10) / 10
    });
}
else {
    return null;
}

// ---- Try to assemble ----

const genBattPart = flow.get("def_part_gen_batt");
const gridLoadPart = flow.get("def_part_grid_load");
const pvPart = flow.get("def_part_pv");

if (!genBattPart || !gridLoadPart || !pvPart) {
    return null;
}

const deviceId = msg.deviceId
    || global.get("DEVICE_ID")
    || env.get("DEVICE_ID")
    || "EC100-DEV-001";

const state = {
    kind: "DailyEnergyFlowState",
    timestampUtc: new Date().toISOString(),
    version: 1,
    DeviceId: deviceId,

    loadEnergyKWh: gridLoadPart.loadEnergyKWh,

    grid: {
        importEnergyKWh: gridLoadPart.importEnergyKWh,
        exportEnergyKWh: gridLoadPart.exportEnergyKWh
    },

    pv: {
        totalEnergyKWh: pvPart.pvEnergyKWh,
        mppt: [
            { id: 1, energyKWh: null },
            { id: 2, energyKWh: null },
            { id: 3, energyKWh: null },
            { id: 4, energyKWh: null }
        ]
    },

    battery: {
        chargeEnergyKWh: genBattPart.chargeEnergyKWh,
        dischargeEnergyKWh: genBattPart.dischargeEnergyKWh
    },

    generator: {
        energyKWh: genBattPart.genEnergyKWh
    }
};

// Clear partials
flow.set("def_part_gen_batt", null);
flow.set("def_part_grid_load", null);
flow.set("def_part_pv", null);

// Get RPC response topic if present
const rpcResponseTopic = flow.get("def_rpc_response_topic");
flow.set("def_rpc_response_topic", null);

flow.set("dailyEnergyFlowStateSnapshot", state);

msg.payload = state;
msg.state = state;
msg.rpcResponseTopic = rpcResponseTopic;

return msg;

if (!msg.rpcResponseTopic) {
    return null;
}

msg.topic = msg.rpcResponseTopic;
return msg;
